export interface DbtManifest {
  nodes: Record<string, DbtManifestNode>;
  sources: Record<string, DbtManifestNode>;
  metadata: {
    dbt_version: string;
    generated_at: string;
    project_name: string;
  };
  parent_map: Record<string, string[]>;
  child_map: Record<string, string[]>;
