// --- catalog.json types (subset) ---

export interface DbtCatalogColumn {
  name: string;
  type: string;
  index: number;
  comment: string | null;
}

export interface DbtCatalogNode {
  unique_id: string;
  metadata: {
    type: string;
    schema: string;
    name: string;
    database: string;
    comment: string | null;
    owner: string | null;
  };
  columns: Record<string, DbtCatalogColumn>;
  stats: Record<
    string,
    { id: string; label: string; value: string | number | null; description: string }
  >;
}

export interface DbtCatalog {
  nodes: Record<string, DbtCatalogNode>;
  sources: Record<string, DbtCatalogNode>;
  metadata: {
    generated_at: string;
  };
}

// --- run_results.json types (subset) ---

export interface DbtRunResult {
  unique_id: string;
  status: "success" | "error" | "skipped" | "warn";
  execution_time: number;
  message: string;
}

export interface DbtRunResults {
  results: DbtRunResult[];
  metadata: {
    generated_at: string;
  };
}

// --- App-level derived types ---

export interface CatalogModel {
  uniqueId: string;
  name: string;
  description: string;
  schema: string;
  database: string;
  materialization: string;
  layer: "staging" | "raw_vault" | "business_vault" | "marts" | "other";
  tags: string[];
  columns: CatalogColumn[];
  dependsOn: string[];   // upstream model names
  referencedBy: string[]; // downstream model names
  lastRunStatus: DbtRunResult["status"] | null;
  lastRunTime: number | null;
  path: string;
}

export interface CatalogColumn {
  name: string;
  type: string;
  description: string;
  index: number;
}
