```typescript
// data-catalog-app/src/lib/artifacts.ts
import type {
  DbtManifest,
  DbtCatalog,
  DbtRunResults,
  DbtManifestNode,
  DbtCatalogNode,
  DbtRunResult,
  CatalogModel,
  CatalogColumn,
} from "./types";

type Layer = CatalogModel["layer"];
const KNOWN_LAYERS: Layer[] = ["staging", "raw_vault", "business_vault", "marts"];

export function inferLayer(fqn: string[]): Layer {
  for (const segment of fqn) {
    if (KNOWN_LAYERS.includes(segment as Layer)) {
      return segment as Layer;
    }
  }
  return "other";
}

export function transformManifestNode(
  node: DbtManifestNode,
  catalogNode: DbtCatalogNode | undefined,
  runResult: DbtRunResult | undefined,
  childMap: Record<string, string[]>
): CatalogModel {
  const columns: CatalogColumn[] = catalogNode
    ? Object.values(catalogNode.columns).map((col) => ({
        name: col.name,
        type: col.type,
        description:
          node.columns[col.name.toLowerCase()]?.description ??
          node.columns[col.name]?.description ??
          "",
        index: col.index,
      }))
    : Object.values(node.columns).map((col, i) => ({
        name: col.name,
        type: col.data_type ?? "unknown",
        description: col.description,
        index: i + 1,
      }));

  columns.sort((a, b) => a.index - b.index);

  return {
    uniqueId: node.unique_id,
    name: node.name,
    description: node.description,
    schema: node.schema,
    database: node.database,
    materialization: node.config.materialized,
    layer: inferLayer(node.fqn),
    tags: node.tags,
    columns,
    dependsOn: node.depends_on.nodes,
    referencedBy: childMap[node.unique_id] ?? [],
    lastRunStatus: runResult?.status ?? null,
    lastRunTime: runResult?.execution_time ?? null,
    path: node.path,
  };
}

async function fetchJson<T>(bucket: R2Bucket, key: string): Promise<T | null> {
  const obj = await bucket.get(key);
  if (!obj) return null;
  return obj.json() as Promise<T>;
}

export async function loadAllModels(bucket: R2Bucket): Promise<CatalogModel[]> {
  const [manifest, catalog, runResults] = await Promise.all([
    fetchJson<DbtManifest>(bucket, "manifest.json"),
    fetchJson<DbtCatalog>(bucket, "catalog.json"),
    fetchJson<DbtRunResults>(bucket, "run_results.json"),
  ]);

  if (!manifest) return [];

  const runResultMap = new Map(
    (runResults?.results ?? []).map((r) => [r.unique_id, r])
  );

  const models: CatalogModel[] = [];
  for (const [key, node] of Object.entries(manifest.nodes)) {
    if (node.resource_type !== "model") continue;
    models.push(
      transformManifestNode(
        node,
        catalog?.nodes?.[key],
        runResultMap.get(key),
        manifest.child_map ?? {}
      )
    );
  }

  models.sort((a, b) => {
    const layerOrder = ["marts", "business_vault", "raw_vault", "staging", "other"];
    const la = layerOrder.indexOf(a.layer);
    const lb = layerOrder.indexOf(b.layer);
    if (la !== lb) return la - lb;
    return a.name.localeCompare(b.name);
  });

  return models;
}

export async function loadModel(
  bucket: R2Bucket,
  modelName: string
): Promise<CatalogModel | null> {
  const models = await loadAllModels(bucket);
  return models.find((m) => m.name === modelName) ?? null;
}

export async function loadManifestMetadata(
  bucket: R2Bucket
): Promise<{ dbtVersion: string; generatedAt: string } | null> {
  const manifest = await fetchJson<DbtManifest>(bucket, "manifest.json");
  if (!manifest) return null;
  return {
    dbtVersion: manifest.metadata.dbt_version,
    generatedAt: manifest.metadata.generated_at,
  };
}
```

