// data-catalog-app/src/components/ModelList.tsx
import { Badge, Input, Surface, Table, Tabs, Text } from "@cloudflare/kumo";
import { useState } from "react";
import type { CatalogModel } from "../lib/types";

function StatusBadge({ status }: { status: CatalogModel["lastRunStatus"] }) {
  if (status === "success") return <Badge variant="green">Success</Badge>;
  if (status === "error") return <Badge variant="red">Error</Badge>;
  if (status === "warn") return <Badge variant="orange">Warning</Badge>;
  if (status === "skipped") return <Badge variant="outline">Skipped</Badge>;
  return <Badge variant="outline">Unknown</Badge>;
}

function LayerBadge({ layer }: { layer: CatalogModel["layer"] }) {
  const variants: Record<string, "blue" | "purple" | "orange" | "green" | "outline"> = {
    marts: "green",
    business_vault: "purple",
    raw_vault: "blue",
    staging: "orange",
    other: "outline",
  };
  return <Badge variant={variants[layer] ?? "outline"}>{layer}</Badge>;
}

const LAYER_TABS = [
  { value: "all", label: "All Models" },
  { value: "marts", label: "Marts" },
  { value: "business_vault", label: "Business Vault" },
  { value: "raw_vault", label: "Raw Vault" },
  { value: "staging", label: "Staging" },
] as const;

interface Props {
  models: CatalogModel[];
}

export function ModelList({ models }: Props) {
  const [search, setSearch] = useState("");
  const [selectedLayer, setSelectedLayer] = useState("all");

  const filtered = models.filter((m) => {
    if (selectedLayer !== "all" && m.layer !== selectedLayer) return false;
    if (!search) return true;
    const q = search.toLowerCase();
    return (
      m.name.toLowerCase().includes(q) ||
      m.description.toLowerCase().includes(q) ||
      m.schema.toLowerCase().includes(q)
    );
  });

  return (
    <div className="flex flex-1 flex-col gap-6 p-6">
      <div>
        <Text className="text-2xl font-bold">Models</Text>
        <Text className="text-kumo-subtle text-sm">
          {models.length} dbt models across your data platform
        </Text>
      </div>

      <Tabs
        variant="underline"
        tabs={LAYER_TABS.map((t) => ({ ...t }))}
        selectedValue={selectedLayer}
        onValueChange={setSelectedLayer}
      />

      <div className="flex items-center gap-4">
        <div className="flex-1">
          <Input
            aria-label="Search models"
            placeholder="Search by name, description, or schema..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <Text className="text-kumo-subtle text-sm whitespace-nowrap">
          {filtered.length} model{filtered.length !== 1 ? "s" : ""}
        </Text>
      </div>

      <Surface className="overflow-hidden rounded-lg">
        <Table>
          <Table.Header>
            <Table.Row>
              <Table.Head>Name</Table.Head>
              <Table.Head>Layer</Table.Head>
              <Table.Head>Schema</Table.Head>
              <Table.Head>Materialization</Table.Head>
              <Table.Head>Columns</Table.Head>
              <Table.Head>Last Run</Table.Head>
            </Table.Row>
          </Table.Header>
          <Table.Body>
            {filtered.map((model) => (
              <Table.Row key={model.uniqueId}>
                <Table.Cell>
                  <a
                    href={`/models/${model.name}`}
                    className="text-kumo-accent hover:underline font-medium"
                  >
                    {model.name}
                  </a>
                  {model.description && (
                    <Text className="text-kumo-subtle text-xs line-clamp-1">
                      {model.description}
                    </Text>
                  )}
                </Table.Cell>
                <Table.Cell>
                  <LayerBadge layer={model.layer} />
                </Table.Cell>
                <Table.Cell className="font-mono text-sm">{model.schema}</Table.Cell>
                <Table.Cell>
                  <Badge variant="outline">{model.materialization}</Badge>
                </Table.Cell>
                <Table.Cell>{model.columns.length}</Table.Cell>
                <Table.Cell>
                  <StatusBadge status={model.lastRunStatus} />
                </Table.Cell>
              </Table.Row>
            ))}
          </Table.Body>
        </Table>
      </Surface>
    </div>
  );
}
