import { Badge, Text } from "@cloudflare/kumo";

function extractName(uniqueId: string): string {
  const parts = uniqueId.split(".");
  return parts[parts.length - 1];
}

interface Props {
  label: string;
  nodeIds: string[];
}

export function LineageBadges({ label, nodeIds }: Props) {
  if (nodeIds.length === 0) return null;

  return (
    <div>
      <Text className="text-kumo-subtle text-xs font-medium mb-1">{label}</Text>
      <div className="flex flex-wrap gap-1">
        {nodeIds.map((id) => {
          const name = extractName(id);
          const isModel = id.startsWith("model.");
          return (
            <a key={id} href={isModel ? `/models/${name}` : "#"}>
              <Badge variant="outline" className="cursor-pointer hover:bg-kumo-subtle">
                {name}
              </Badge>
            </a>
          );
        })}
      </div>
    </div>
  );
}
