```tsx
// data-catalog-app/src/components/SearchPage.tsx
import { Button, Input, Surface, Text } from "@cloudflare/kumo";
import { MagnifyingGlass } from "@phosphor-icons/react";
import { useState } from "react";

interface SearchResult {
  response?: string;
  data?: Array<{
    source: string;
    content: string;
    score: number;
  }>;
  error?: string;
}

export function SearchPage() {
  const [query, setQuery] = useState("");
  const [result, setResult] = useState<SearchResult | null>(null);
  const [loading, setLoading] = useState(false);

  async function handleSearch(e: React.FormEvent) {
    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    setResult(null);
    try {
      const res = await fetch("/api/search", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query }),
      });
      const data = await res.json();
      setResult(data);
    } catch {
      setResult({ error: "Search request failed" });
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="flex flex-1 flex-col gap-6 p-6">
      <div>
        <Text className="text-2xl font-bold">Search</Text>
        <Text className="text-kumo-subtle text-sm">
          Ask questions about your data in natural language
        </Text>
      </div>

      <form onSubmit={handleSearch} className="flex gap-2">
        <div className="flex-1">
          <Input
            aria-label="Search query"
            placeholder="例: 患者に関連するテーブルは？"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </div>
        <Button
          type="submit"
          variant="primary"
          icon={<MagnifyingGlass size={16} />}
          disabled={loading}
        >
          {loading ? "Searching..." : "Search"}
        </Button>
      </form>

      {result?.error && (
        <Surface className="rounded-lg p-4 border-red-200">
          <Text className="text-red-600 text-sm">{result.error}</Text>
        </Surface>
      )}

      {result?.response && (
        <Surface className="rounded-lg p-4">
          <Text className="text-sm font-medium mb-2">AI Answer</Text>
          <Text className="text-sm whitespace-pre-wrap">{result.response}</Text>
        </Surface>
      )}

      {result?.data && result.data.length > 0 && (
        <div className="flex flex-col gap-3">
          <Text className="text-sm font-medium">Sources</Text>
          {result.data.map((item, i) => (
            <Surface key={i} className="rounded-lg p-4">
              <Text className="text-xs text-kumo-subtle mb-1">{item.source}</Text>
              <Text className="text-sm">{item.content}</Text>
              <Text className="text-xs text-kumo-subtle mt-1">
                Relevance: {(item.score * 100).toFixed(0)}%
              </Text>
            </Surface>
          ))}
        </div>
      )}
    </div>
  );
}
```

